import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Build the group container
  const group = new THREE.Group();

  // Create plane geometry (unit quad, 2x1.25 aspect for 512x320 atlas region)
  const geometry = new THREE.PlaneGeometry(2, 1.25, 1, 1);

  // Load the brushed-metal texture asynchronously
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Create material with TSL nodes
  const material = new MeshBasicNodeMaterial({
    side: THREE.DoubleSide,
    transparent: true,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Store timeline references for cleanup
  const timelines = [];

  // Setup texture once loaded, then create text layer
  texturePromise.then((tex) => {
    // Set the texture on the material
    material.colorNode = texture(tex, uv());
    material.needsUpdate = true;

    // Create text overlay: "Collection 2" at headline size (39px = 0.195 scene units approx at fontSize 39)
    const textObj = ctx.fontAtlas.createText('Collection 2', {
      fontSize: 39,
      color: '#e8ecf2', // paper color for contrast
      align: 'center',
    });

    // Position text slightly forward on the z-axis to ensure it renders above the plane
    textObj.position.z = 0.1;
    group.add(textObj);
  }).catch((err) => {
    console.error('[Collection 2 Label] Texture load failed:', err);
  });

  // Apply scene position from config (adapter will handle this, but ensure it's set)
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x ?? 0,
      config.scenePosition.y ?? 0,
      config.scenePosition.z ?? 0
    );
  } else {
    // Fallback to position from spec
    group.position.set(0, 1, 0.06);
  }

  // Apply rotation (identity in this case)
  if (config.rotation) {
    group.rotation.order = 'YXZ';
    group.rotation.set(
      config.rotation.x ?? 0,
      config.rotation.y ?? 0,
      config.rotation.z ?? 0
    );
  }

  // Apply scale
  if (config.scale) {
    group.scale.set(
      config.scale.x ?? 1,
      config.scale.y ?? 1,
      config.scale.z ?? 1
    );
  }

  // Setup userData handlers (no interactions specified, but structure for compatibility)
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = () => {
    // Kill all active timelines
    timelines.forEach((tl) => {
      if (tl) tl.kill();
    });

    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose texture if it was loaded
    texturePromise.then((tex) => {
      tex.dispose();
    }).catch(() => {
      // Suppress error if texture load failed
    });
  };

  return group;
}
